OLD = "\tsize_t faceVetoKept = 0, faceVetoDropped = 0;\n\tfor (int i = 0; i < cloud->points.size(); i++)\n\t{\n\t\tif (boundary[i].boundary_point == 1)\n\t\t{\n\t\t\tEigen::Vector3f rp = cloudWithoutNormals->points[i].getVector3fMap() - surfCentroid;\n\t\t\tfloat rl = rp.norm();\n\t\t\tEigen::Vector3f nn(normals->points[i].normal_x, normals->points[i].normal_y, normals->points[i].normal_z);\n\t\t\tfloat align = (rl > 1e-6f) ? nn.dot(rp / rl) : 0.0f;\n\t\t\tif (align <= FACE_ALIGN_VETO)\n\t\t\t{\n\t\t\t\tboundaryCloud->points.push_back(cloudWithoutNormals->points[i]);\n\t\t\t\tfaceVetoKept++;\n\t\t\t}\n\t\t\telse faceVetoDropped++;\n\t\t}\n\t}\n\tstd::cout << \"[FACE VETO] boundary kept=\" << faceVetoKept << \" dropped=\" << faceVetoDropped\n\t          << \" (align<= \" << FACE_ALIGN_VETO << \", centroid-observable)\" << std::endl;"
NEW = "\t// POTA-159 adaptive face veto (ORIG-free; same-binary ORIG control = env unset).\n\t// Collect admitted aligns first (read-only stats feed the distribution\n\t// analysis). POTA159_ADAPT=1: per-surface Otsu threshold on the piece's own\n\t// align distribution, clamped to [0.5, 0.95]; unset: fixed 0.5 (155 rule).\n\t// Floor 0.5 = 155-proven Pot-A point (adapt may only keep MORE, never veto\n\t// more); cap 0.95 keeps the veto load-bearing (158: off is strictly worse).\n\tstd::vector<float> admitAlign; admitAlign.reserve(1024);\n\tstd::vector<int> admitIdx; admitIdx.reserve(1024);\n\tfor (int i = 0; i < (int)cloud->points.size(); i++)\n\t{\n\t\tif (boundary[i].boundary_point == 1)\n\t\t{\n\t\t\tEigen::Vector3f rp = cloudWithoutNormals->points[i].getVector3fMap() - surfCentroid;\n\t\t\tfloat rl = rp.norm();\n\t\t\tEigen::Vector3f nn(normals->points[i].normal_x, normals->points[i].normal_y, normals->points[i].normal_z);\n\t\t\tfloat align = (rl > 1e-6f) ? nn.dot(rp / rl) : 0.0f;\n\t\t\tadmitAlign.push_back(align);\n\t\t\tadmitIdx.push_back(i);\n\t\t}\n\t}\n\tfloat faceVetoThresh = FACE_ALIGN_VETO;\n\t{\n\t\tint hbins[20] = {0};\n\t\tfor (size_t k = 0; k < admitAlign.size(); k++)\n\t\t{\n\t\t\tint b = (int)((admitAlign[k] + 1.0f) * 10.0f);\n\t\t\tif (b < 0) b = 0; if (b > 19) b = 19; hbins[b]++;\n\t\t}\n\t\tstd::ostringstream hs; for (int b = 0; b < 20; b++) { if (b) hs << \",\"; hs << hbins[b]; }\n\t\tconst int NB = 256; long h256[256] = {0};\n\t\tfor (size_t k = 0; k < admitAlign.size(); k++)\n\t\t{\n\t\t\tint b = (int)((admitAlign[k] + 1.0f) * 128.0f);\n\t\t\tif (b < 0) b = 0; if (b > 255) b = 255; h256[b]++;\n\t\t}\n\t\tlong nT = (long)admitAlign.size(); double sT = 0.0;\n\t\tfor (int b = 0; b < NB; b++) sT += b * (double)h256[b];\n\t\tdouble sB = 0.0; long wB = 0; double bestVar = -1.0; int bestB = -1;\n\t\tfor (int b = 0; b < NB; b++)\n\t\t{\n\t\t\twB += h256[b]; if (wB == 0) continue;\n\t\t\tlong wF = nT - wB; if (wF == 0) break;\n\t\t\tsB += b * (double)h256[b];\n\t\t\tdouble mB = sB / wB, mF = (sT - sB) / wF;\n\t\t\tdouble v = (double)wB * wF * (mB - mF) * (mB - mF);\n\t\t\tif (v > bestVar) { bestVar = v; bestB = b; }\n\t\t}\n\t\tfloat otsuThr = (bestB >= 0) ? ((bestB + 0.5f) / 128.0f - 1.0f) : FACE_ALIGN_VETO;\n\t\tstatic int vetoCall = 0;\n\t\tconst char* adaptEnv = std::getenv(\"POTA159_ADAPT\");\n\t\tbool adapt = (adaptEnv && std::string(adaptEnv) == \"1\");\n\t\tif (adapt)\n\t\t{\n\t\t\tfaceVetoThresh = otsuThr;\n\t\t\tif (faceVetoThresh < 0.5f) faceVetoThresh = 0.5f;\n\t\t\tif (faceVetoThresh > 0.95f) faceVetoThresh = 0.95f;\n\t\t}\n\t\tstd::cout << \"[ADAPT VETO] call=\" << vetoCall << \" n=\" << nT << \" otsu=\" << otsuThr\n\t\t          << \" thr=\" << faceVetoThresh << (adapt ? \" ADAPT\" : \" FIXED\")\n\t\t          << \" hist20=\" << hs.str() << std::endl;\n\t\tif (adapt)\n\t\t{\n\t\t\tstd::string piece = currentMeshFile.empty() ? \"unknown\" : std::experimental::filesystem::path(currentMeshFile).stem().string().substr(0,14);\n\t\t\tstd::string csv = tempEdgeFolder + \"veto_align_\" + piece + \"_c\" + std::to_string(vetoCall) + \".csv\";\n\t\t\tstd::ofstream cf(csv); cf << \"x,y,z,align,kept\\n\";\n\t\t\tfor (size_t k = 0; k < admitAlign.size(); k++)\n\t\t\t{\n\t\t\t\tint ii = admitIdx[k];\n\t\t\t\tcf << cloudWithoutNormals->points[ii].x << \",\" << cloudWithoutNormals->points[ii].y << \",\" << cloudWithoutNormals->points[ii].z\n\t\t\t\t   << \",\" << admitAlign[k] << \",\" << (admitAlign[k] <= faceVetoThresh ? 1 : 0) << \"\\n\";\n\t\t\t}\n\t\t}\n\t\tvetoCall++;\n\t}\n\tsize_t faceVetoKept = 0, faceVetoDropped = 0;\n\tfor (size_t k = 0; k < admitAlign.size(); k++)\n\t{\n\t\tif (admitAlign[k] <= faceVetoThresh)\n\t\t{\n\t\t\tboundaryCloud->points.push_back(cloudWithoutNormals->points[admitIdx[k]]);\n\t\t\tfaceVetoKept++;\n\t\t}\n\t\telse faceVetoDropped++;\n\t}\n\tstd::cout << \"[FACE VETO] boundary kept=\" << faceVetoKept << \" dropped=\" << faceVetoDropped\n\t          << \" (align<= \" << faceVetoThresh << \", centroid-observable)\" << std::endl;"
